<script setup>
import { computed, ref } from 'vue'
import { useMarketDashboard } from './useMarketDashboard.js'
import { dateTime, movement, number } from './model.js'
import PrototypeChart from './PrototypeChart.vue'

const {data,loading,error,refresh}=useMarketDashboard()
const emit=defineEmits(['select'])
const expanded=ref(false),leaderMode=ref('leaders'),selected=ref(''),hotMode=ref('industry')
const developer=new URLSearchParams(location.search).get('developer')==='1'
const industries=computed(()=>data.value?.industries||[])
const visibleIndustries=computed(()=>expanded.value?industries.value:industries.value.slice(0,10))
const hotSectors=computed(()=>hotMode.value==='industry'?[...industries.value].sort((a,b)=>b.amount-a.amount).slice(0,10):data.value?.hot_sectors||[])
const activeSector=computed(()=>hotSectors.value.find(g=>g.id===selected.value)||hotSectors.value[0])
const amount=value=>number(value/1e8,1)
const pct=value=>(value>0?'+':'')+number(value)+'%'
const status=computed(()=>error.value||data.value?.refresh_error?'刷新异常，保留上次报价':data.value?.freshness==='LIVE'?'盘中行情 · 30秒刷新':data.value?.freshness==='DELAYED'?'报价延迟':'最近交易报价 · 30秒刷新')
const chart=computed(()=>({kind:'sector_rank',title:'行业涨跌幅排名：成分股等权平均',chart_type:'bar',x:industries.value.slice(0,10).map(g=>g.name),series:[{name:'成分股平均涨跌幅 %',axis:0,type:'bar',signed:true,data:industries.value.slice(0,10).map(g=>g.change)}]}))
const summary=computed(()=>{
  if(!industries.value.length)return ''
  const positive=industries.value.filter(g=>g.change>0).length
  return positive?`${positive} 个行业均值上涨，${industries.value[0].name}居前`:`当前行业均值均下跌，${industries.value[0].name}跌幅最小`
})
</script>
<template>
  <section class="workspace-section market-dashboard" aria-label="市场热点与行业龙头">
    <div class="section-heading market-heading"><div><h2>市场热点与行业龙头</h2><p class="condition-note">{{ status }}<template v-if="data"> · 报价 {{ dateTime(data.quoted_to) }}</template></p></div><button class="btn" :disabled="loading" @click="refresh">{{ loading?'刷新中…':'刷新行情' }}</button></div>
    <p v-if="error||data?.refresh_error" class="notice error-text" role="alert">{{ error||data.refresh_error }}</p>
    <div v-if="!data" class="panel market-loading" role="status">{{ loading?'正在读取行业成分与最新行情，首次加载可能需要一分钟…':'尚未取得市场行情，请刷新重试。' }}</div>
    <template v-else>
      <div class="market-lead"><strong>{{ summary }}</strong><span class="condition-note">已覆盖 {{ data.coverage.industries_ranked }}/{{ data.coverage.industries_expected }} 行业 · {{ data.coverage.concepts_ranked }}/{{ data.coverage.concepts_expected }} 概念 · {{ data.coverage.stocks_quoted }} 只股票</span></div>
      <p v-if="data.partial" class="condition-note market-partial">部分成分报价或分类未齐全，仅在完整成分取得报价的板块中排名。</p>
      <div class="market-grid">
        <article class="panel market-hot"><div class="market-card-heading"><h3>热门板块</h3><div class="leader-options" role="group" aria-label="热门板块分类"><button class="chip" :aria-pressed="hotMode==='industry'" @click="hotMode='industry'">行业热度</button><button class="chip" :aria-pressed="hotMode==='concept'" @click="hotMode='concept'">概念热度</button></div></div>
          <p class="condition-note">当日累计成交额 Top 10</p><div class="hot-list"><button v-for="(g,i) in hotSectors" :key="g.id" class="hot-row" :class="{'is-selected':activeSector?.id===g.id}" :aria-pressed="activeSector?.id===g.id" @click="selected=g.id"><span class="rank num">{{ i+1 }}</span><span class="hot-name">{{ g.name }}<span class="hot-meter" :style="{width:(g.amount/hotSectors[0].amount*100)+'%'}"></span></span><span class="num hot-amount">{{ amount(g.amount) }}<small>亿</small></span><strong class="num" :class="movement(g.change)">{{ pct(g.change) }}</strong></button></div>
          <div v-if="activeSector" class="sector-members"><div class="market-card-heading"><h4>{{ activeSector.name }} · 成交活跃股</h4><span class="condition-note">{{ activeSector.active_count }} 只成交</span></div><button v-for="q in activeSector.trading_leaders" :key="q.code" class="member-quote" @click="emit('select',q)" :title="'报价 '+dateTime(q.quoted_at)"><span>{{ q.name }} <small class="muted">{{ q.code }}</small></span><span class="num">{{ amount(q.amount) }}亿</span><strong class="num" :class="movement(q.change)">{{ pct(q.change) }}</strong></button></div>
          <p class="condition-note">概念有重叠；热度表示成交活跃，可能同时下跌。</p>
        </article>
        <article class="panel market-chart"><div class="market-card-heading"><h3>行业涨跌幅榜</h3><span class="condition-note">成分股等权平均 Top 10</span></div><PrototypeChart :block="chart" :height="292"/><div class="industry-pulse"><span>上涨行业 <strong class="up">{{ industries.filter(g=>g.change>0).length }}</strong></span><span>下跌行业 <strong class="down">{{ industries.filter(g=>g.change<0).length }}</strong></span><span>持平 <strong>{{ industries.filter(g=>g.change===0).length }}</strong></span></div><p class="condition-note">申万一级行业，按有成交的成分股计算；全跌时展示跌幅最小的行业。</p></article>
      </div>
      <article class="panel industry-leaders"><div class="market-card-heading"><div><h3>各行业龙头观察</h3><p class="condition-note">{{ leaderMode==='leaders'?'总市值前三只代表股':'当日累计成交额前三只活跃股' }} · 行情排序 · 点击股票填入上方研究框</p></div><div class="leader-options" role="group" aria-label="行业代表股排序"><button class="chip" :aria-pressed="leaderMode==='leaders'" @click="leaderMode='leaders'">市值龙头</button><button class="chip" :aria-pressed="leaderMode==='trading_leaders'" @click="leaderMode='trading_leaders'">成交龙头</button></div></div>
        <div class="industry-head"><span>行业 / 平均涨跌</span><span>成交额 / 涨跌家数</span><span>行业代表股 · 价格 / 涨跌幅</span></div>
        <div v-for="(g,i) in visibleIndustries" :key="g.id" class="industry-row"><div class="industry-name"><span class="rank num">{{ i+1 }}</span><div><strong>{{ g.name }}</strong><span class="num" :class="movement(g.change)">{{ pct(g.change) }}</span></div></div><div class="industry-breadth"><strong class="num">{{ amount(g.amount) }}亿</strong><span><b class="up">涨 {{ g.up }}</b> / <b class="down">跌 {{ g.down }}</b><small> · {{ g.count }} 只</small></span></div><div class="industry-stocks"><button v-for="q in g[leaderMode]" :key="q.code" @click="emit('select',q)" :title="'报价 '+dateTime(q.quoted_at)+(leaderMode==='leaders'?' · 总市值 '+amount(q.market_cap):' · 成交额 '+amount(q.amount))+'亿元'"><span>{{ q.name }}<small class="muted">{{ q.code }}</small></span><span class="num">{{ number(q.price) }} <strong :class="movement(q.change)">{{ pct(q.change) }}</strong></span></button></div></div>
        <button v-if="industries.length>10" class="btn show-industries" :aria-expanded="expanded" @click="expanded=!expanded">{{ expanded?'收起行业':'展开全部 '+industries.length+' 个行业' }}</button>
      </article>
      <details class="market-source"><summary>数据来源与榜单口径</summary><p>{{ data.methodology.scope }}。{{ data.methodology.hot }}。{{ data.methodology.gain }}。{{ data.methodology.leaders }}。</p><p>行情：腾讯证券；行业：Tushare 申万2021；概念：新浪财经。报价范围 {{ dateTime(data.quoted_from) }} — {{ dateTime(data.quoted_to) }}；本次读取 {{ dateTime(data.retrieved_at) }}；分类读取 {{ dateTime(data.classification_at) }}。页面前台每30秒取数，休市保留最近报价；普通互联网行情存在传输延迟。</p><pre v-if="developer">{{ JSON.stringify({coverage:data.coverage,sources:data.sources},null,2) }}</pre></details>
    </template>
  </section>
</template>
<style scoped>
.market-heading{align-items:center}.market-heading p{margin:5px 0 0}.market-lead{display:flex;justify-content:space-between;gap:12px;margin:12px 0}.market-lead>strong{font-size:14px}.market-partial{margin:4px 0 12px;color:var(--warn)}.market-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.market-grid>.panel,.industry-leaders{padding:16px 18px;min-width:0}.market-card-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:10px}.market-card-heading :is(h3,h4){margin:0;font-size:14px}.market-card-heading p{margin:5px 0 0}.hot-row{display:grid;grid-template-columns:22px minmax(0,1fr) 76px 72px;align-items:center;gap:6px;width:100%;background:transparent;border:0;border-bottom:1px solid var(--border);padding:8px 4px;text-align:left;cursor:pointer;color:var(--text-1);font:inherit;font-size:12px}.hot-row:hover,.hot-row.is-selected{background:var(--bg-raised)}.rank{color:var(--text-3);font-size:11px}.hot-name{position:relative;padding-bottom:5px}.hot-meter{position:absolute;bottom:0;left:0;height:2px;background:var(--accent);opacity:.5}.hot-amount,.hot-row>strong{text-align:right}.hot-amount small{font-size:10px;margin-left:3px;color:var(--text-3)}.sector-members{margin-top:14px;padding-top:12px;border-top:1px solid var(--border)}.sector-members h4{font-size:12px}.member-quote{width:100%;background:transparent;border:0;text-align:left;cursor:pointer;font:inherit;display:grid;grid-template-columns:1fr 70px 70px;gap:6px;font-size:12px;padding:7px 0;color:var(--text-1);text-decoration:none}.member-quote>span:not(:first-child),.member-quote>strong{text-align:right}.industry-pulse{display:flex;justify-content:space-around;gap:10px;padding:16px 0;border-top:1px solid var(--border);font-size:12px}.industry-pulse strong{margin-left:8px;font-size:18px}.industry-leaders{margin-top:12px}.leader-options{display:flex;gap:6px}.leader-options [aria-pressed=true]{border-color:var(--accent);color:var(--accent)}.industry-head,.industry-row{display:grid;grid-template-columns:155px 160px minmax(0,1fr);gap:16px}.industry-head{font-size:11px;color:var(--text-3);padding:10px 0;border-bottom:1px solid var(--border)}.industry-row{align-items:center;padding:12px 0;border-bottom:1px solid var(--border)}.industry-name{display:flex;align-items:center;gap:10px}.industry-name>div{display:flex;flex-direction:column;gap:5px;font-size:12px}.industry-name .num{font-size:12px}.industry-breadth{display:flex;flex-direction:column;gap:6px;font-size:12px}.industry-breadth>span{font-size:10px;color:var(--text-3)}.industry-breadth b{font-weight:400}.industry-stocks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.industry-stocks button{background:transparent;border:0;text-align:left;cursor:pointer;font:inherit;padding:0;display:flex;flex-direction:column;gap:5px;color:var(--text-1);font-size:12px;text-decoration:none}.industry-stocks small{display:block;font-size:10px;line-height:1.6}.industry-stocks .num{font-size:11px;white-space:nowrap}.industry-stocks strong{margin-left:5px}.member-quote:hover,.industry-stocks button:hover{color:var(--accent)}.show-industries{display:block;margin:14px auto 0}.market-source{font-size:11px;color:var(--text-3);line-height:1.8;margin-top:12px}.market-source summary{cursor:pointer}.market-source pre{max-height:250px;overflow:auto}.market-loading{padding:25px}.market-dashboard :is(button,summary):focus-visible{outline:2px solid var(--accent);outline-offset:3px}@media(max-width:1000px){.industry-head,.industry-row{grid-template-columns:120px 130px minmax(0,1fr);gap:10px}.industry-stocks{gap:6px}.market-lead{flex-direction:column}}@media(max-width:760px){.market-grid{grid-template-columns:1fr}.market-card-heading{flex-wrap:wrap}.industry-head{display:none}.industry-row{grid-template-columns:1fr 1fr}.industry-stocks{grid-column:1/-1;padding-top:8px}.industry-breadth{text-align:right}.market-heading{gap:8px}.market-heading h2{font-size:17px}.market-heading .btn{white-space:nowrap}.market-grid>.panel,.industry-leaders{padding:14px 12px}}
</style>
